ROOT=Path(__file__).resolve().parents[1];SRC=Path('/workspace/shared/atlas-research/company-onboarding/ASML');OUT=ROOT/'dist/data/incremental-ASML-2026-10-18-v4';OUT.mkdir(parents=True,exist_ok=True)
