 parts.append('<section><h2>December 31, 2025 / 2025 年 12 月 31 日</h2><p>EV / 企业价值 EUR 280,842.053059 million · EUR 745.971695 / share 每股 · USD 876.516742 at dated FX 日期汇率 1.175</p><div class="table-wrap"><table><tr><th>Period / 期间</th><th>Revenue EURm / 收入</th><th>Margin / 利润率</th><th>Net investment EURm / 净投资</th><th>WACC</th></tr>')
